BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(27);
SELECT ok(to_regclass('app_private.admission_student_handoffs') IS NOT NULL,'P38 private handoff table installed');
SELECT is((SELECT relowner::regrole::text FROM pg_class WHERE oid='app_private.admission_student_handoffs'::regclass),'schoolos_schema_owner'::text,'only schema owner owns handoff table');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.admission_student_handoffs'::regclass),'handoff row-level security enabled and forced');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='p'),'handoff UUID primary key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='u' AND conkey=(SELECT array_agg(attnum ORDER BY attnum)::int2[] FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='application_id')),'at most one handoff per application');
SELECT ok((SELECT count(*)>=8 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='f'),'typed application/Forward/Person/Section/Student/receipt foreign keys');
SELECT ok((SELECT count(*)>=4 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='u'),'distinct replay and result identifier uniqueness');
SELECT ok((SELECT count(*)>=2 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='c'),'state and consumed-result integrity constraints');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND contype='f' AND confrelid='app_private.admission_document_forwards'::regclass AND cardinality(conkey)=2),'forward tied to exact application by composite FK');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgrelid='app_private.admission_student_handoffs'::regclass AND tgname='db03_handoff_mutation_disabled' AND NOT tgisinternal),'all row mutations fenced');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgrelid='app_private.admission_student_handoffs'::regclass AND tgname='db03_handoff_no_truncate' AND NOT tgisinternal),'truncate fenced');
SELECT ok(to_regprocedure('app_private.db03_student_handoff_mutation_unavailable()') IS NOT NULL,'P38 fixed mutation-denial function exists');
SELECT ok(NOT (SELECT prosecdef FROM pg_proc WHERE oid='app_private.db03_student_handoff_mutation_unavailable()'::regprocedure),'P38 denial function SECURITY INVOKER');
SELECT ok((SELECT EXISTS(SELECT 1 FROM unnest(proconfig) AS config(setting) WHERE regexp_replace(config.setting,'[[:space:]]','','g')='search_path=pg_catalog,pg_temp') FROM pg_proc WHERE oid='app_private.db03_student_handoff_mutation_unavailable()'::regprocedure),'P38 denial function fixes safe search_path');
SELECT ok((SELECT count(*)=1 FROM pg_policies WHERE schemaname='app_private' AND tablename='admission_student_handoffs' AND policyname='db03_handoff_storage_owner' AND roles=ARRAY['schoolos_schema_owner']::name[]),'only one owner policy exists');
SELECT ok(NOT has_table_privilege('anon','app_private.admission_student_handoffs','SELECT') AND NOT has_table_privilege('anon','app_private.admission_student_handoffs','INSERT'),'anon cannot read or create handoffs');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','SELECT') AND NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT'),'authenticated cannot read or create handoffs');
SELECT ok(NOT has_table_privilege('service_role','app_private.admission_student_handoffs','SELECT') AND NOT has_table_privilege('service_role','app_private.admission_student_handoffs','INSERT'),'service_role cannot read or create handoffs');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_student_handoffs','SELECT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_student_handoffs','INSERT'),'Admissions workflow cannot issue handoffs');
SELECT ok(NOT has_table_privilege('schoolos_student_executor','app_private.admission_student_handoffs','SELECT') AND NOT has_table_privilege('schoolos_student_executor','app_private.admission_student_handoffs','UPDATE'),'D1 Student executor cannot consume handoffs');
SELECT ok(NOT has_table_privilege('schoolos_evidence_writer','app_private.admission_student_handoffs','SELECT') AND NOT has_table_privilege('schoolos_evidence_writer','app_private.admission_student_handoffs','INSERT'),'evidence executor cannot create handoffs');
SELECT ok(NOT has_table_privilege('schoolos_identity_executor','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('schoolos_platform_executor','app_private.admission_student_handoffs','INSERT'),'identity/platform cannot forge final handoffs');
SELECT ok(NOT has_table_privilege('schoolos_file_login','app_private.admission_student_handoffs','INSERT'),'file worker cannot forge final handoffs');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db03_student_handoff_mutation_unavailable()','EXECUTE') AND NOT has_function_privilege('schoolos_workflow_executor','app_private.db03_student_handoff_mutation_unavailable()','EXECUTE'),'fence function not exposed to public/workflow');
SELECT throws_ok($q$INSERT INTO app_private.admission_student_handoffs DEFAULT VALUES$q$,'P0001','DB03 atomic Student handoff writer unavailable','even owner/root cannot INSERT a forged handoff');
SELECT throws_ok($q$TRUNCATE app_private.admission_student_handoffs$q$,'P0001','DB03 atomic Student handoff writer unavailable','even owner/root cannot TRUNCATE handoff history');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'P38 does not add a public final APPROVE RPC');
SELECT * FROM finish();
ROLLBACK;
